# Feature Flag
#
# Feature Flags management module
#
# This module will allow set Feature Flags to the module to quicker release
# features with less risk
#
# Include design description
# This module depends on Config Include
# Config module will depend on invokeCommand.helper.ps1, MyWrite.ps1, config.ps1, module.helper.ps1
#
# As you se features keys they will be recorded on a config file.
# Deprecate the FF to have it removed from the config file when the FF is released (aka set functionality to GA with now FF.
# Use Clear-FeatureFlagsRegistered to remove deprecated FF from config

$MODULE_NAME = $PSScriptRoot | Split-Path -Parent | Get-ChildItem  -Filter *.psd1 | Select-Object -First 1 | Split-Path -LeafBase

if(-Not $MODULE_NAME){ throw "Module name not found. Please check the module structure." }

$script:FeatureFlags = @{}

function Get-FeatureFlags{
    [CmdletBinding()]
    param()

    $config = Get-Configuration

    if(! $config){
        return @{}
    }

    if(! $config.FeatureFlags){
        $config.FeatureFlags = @{}
    }

    return $config.FeatureFlags
}

function Set-FeatureFlag{
        [CmdletBinding()]
    param(
        [Parameter(Mandatory,Position=0)][string]$Key,
        [Parameter(Mandatory,Position=1)][bool]$Value

    )

    $config = Get-Configuration

    if(! $config){
        throw "Configuration not found."
    }

    if(! $config.FeatureFlags){
        $config.FeatureFlags = @{}
    }

    $config.FeatureFlags.$Key = $Value

    Save-Configuration -Config $config
}

function Test-FeatureFlag {
    [CmdletBinding()]
    [Alias("tff")]
    param(
        [Parameter(Mandatory,Position=0)][string]$Key
    )

    $ffs = Get-FeatureFlags

    $value = $ffs.$Key

    if($null -eq $value){
        Set-FeatureFlag -Key $Key -Value $false
        return $false
    }

    return $value
}

function Register-FeatureFlag{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory,Position=0)][string]$Key,
        [Parameter(Mandatory,Position=1)][string]$Description
    )

    $script:FeatureFlags.$Key = $Description

}

$FeatureFlags_ParameterKeys = {
    param($commandName, $parameterName, $wordToComplete, $commandAst, $fakeBoundParameters)
    $list = $script:FeatureFlags.Keys
    $list | ConvertTo-CompleteResults -wordToComplete $wordToComplete
}
######

function Get-ModuleNameFeatureFlagRegistered{
    [cmdletbinding()]
    [Alias("getFeatureFlagRegistered")]
    param()

    return $script:FeatureFlags

}
$function = "Get-ModuleNameFeatureFlagRegistered"
$destFunction = $function -replace "ModuleName", $MODULE_NAME
if( -not (Test-Path function:$destFunction )){
    Copy-Item -path Function:$function -Destination Function:$destFunction
    Export-ModuleMember -Function $destFunction
}

function Get-ModuleNameFeatureFlag{
    [cmdletbinding()]
    param()

    $ffs = Get-FeatureFlags

    return $ffs
}
$function = "Get-ModuleNameFeatureFlag"
$destFunction = $function -replace "ModuleName", $MODULE_NAME
if( -not (Test-Path function:$destFunction )){
    Copy-Item -path Function:$function -Destination Function:$destFunction
    Export-ModuleMember -Function $destFunction
}


function Enable-ModuleNameFeatureFlag{
    [cmdletbinding()]
    param(
        [Parameter(Mandatory,Position=0)][string]$Key
    )

    Set-FeatureFlag -Key $Key -Value $true
}
$function = "Enable-ModuleNameFeatureFlag"
$destFunction = $function -replace "ModuleName", $MODULE_NAME
if( -not (Test-Path function:$destFunction )){
    Copy-Item -path Function:$function -Destination Function:$destFunction
    Export-ModuleMember -Function $destFunction
    Register-ArgumentCompleter -CommandName $destFunction -ParameterName "Key" -ScriptBlock $FeatureFlags_ParameterKeys
}

function Disable-ModuleNameFeatureFlag{
    [cmdletbinding()]
    param(
        [Parameter(Mandatory,Position=0)][string]$Key
    )

    Set-FeatureFlag -Key $Key -Value $false
}
$function = "Disable-ModuleNameFeatureFlag"
$destFunction = $function -replace "ModuleName", $MODULE_NAME
if( -not (Test-Path function:$destFunction )){
    Copy-Item -path Function:$function -Destination Function:$destFunction
    Export-ModuleMember -Function $destFunction
    Register-ArgumentCompleter -CommandName $destFunction -ParameterName "Key" -ScriptBlock $FeatureFlags_ParameterKeys
}
